INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Olpers Full Cream UHT Milk 1L', 'FrieslandCampina Engro UHT milk. Rich, full-fat and shelf-stable. Ideal for everyday use in tea, cooking and drinking. No refrigeration needed until opened.', 270, 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=400', 150, 'c0000001-0000-0000-0000-000000000001'),
  ('Nestle Milkpak UHT Milk 1L', 'Pakistan long-standing benchmark UHT milk by Nestle. Consistent quality, rich taste and fortified with essential vitamins. A staple in every household.', 265, 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=400', 130, 'c0000001-0000-0000-0000-000000000001'),
  ('Nurpur UHT Full Cream Milk 1L', 'Premium full-cream UHT milk from Nurpur. Known for its rich, creamy taste - the highest-fat UHT option in the market. Perfect for a thick cup of chai.', 285, 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=400', 100, 'c0000001-0000-0000-0000-000000000001'),
  ('Haleeb Full Cream UHT Milk 1L', 'Widely available full-cream UHT milk with a smooth, mild flavour. Good everyday value for the whole family.', 255, 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=400', 90, 'c0000001-0000-0000-0000-000000000001'),
  ('Olpers Lite UHT Milk 1L', 'Low-fat variant of Olpers UHT milk. Same trusted quality with reduced fat content - ideal for health-conscious consumers who do not want to compromise on taste.', 260, 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=400', 80, 'c0000001-0000-0000-0000-000000000001'),
  ('Nido Full Cream Powder 400g', 'Nestle market-leading powdered milk. Rich in calcium and essential vitamins. Dissolves smoothly for a creamy glass of milk or a thick tea whitener. Trusted by Pakistani families for decades.', 720, 'https://images.unsplash.com/photo-1622484211148-c931b1b62ba2?w=400', 90, 'c0000001-0000-0000-0000-000000000001'),
  ('Nestle Everyday Tea Whitener 400g', 'The go-to tea whitener for the perfect cup of doodh patti chai. Creamy, consistent and easy to dissolve. Also used in baking and desserts.', 580, 'https://images.unsplash.com/photo-1622484211148-c931b1b62ba2?w=400', 110, 'c0000001-0000-0000-0000-000000000001'),
  ('Nurpur Butter 200g Salted', 'Pakistan most widely used branded butter. Rich, creamy salted butter made from pure cow milk. Perfect for parathas, toast, baking and cooking.', 420, 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?w=400', 70, 'c0000001-0000-0000-0000-000000000001'),
  ('Olpers Butter 200g Unsalted', 'Smooth, mild unsalted butter from Olpers - ideal for baking where precise salt control matters. Also great for spreading on fresh bread or adding to daal.', 400, 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?w=400', 60, 'c0000001-0000-0000-0000-000000000001'),
  ('Lurpak Butter 200g Imported', 'Premium Danish imported butter. Exceptionally creamy with a signature mild taste. Available at select Islamabad stores. The choice for serious bakers and gourmet cooking.', 950, 'https://images.unsplash.com/photo-1589985270826-4b7bb135bc9d?w=400', 25, 'c0000001-0000-0000-0000-000000000001'),
  ('Nurpur Cheddar Cheese Slices 200g', 'Pakistan most widely available cheddar cheese. Individually wrapped slices that melt beautifully on burgers and sandwiches. Consistent quality throughout.', 540, 'https://images.unsplash.com/photo-1618164436241-4473940d1f5c?w=400', 55, 'c0000001-0000-0000-0000-000000000001'),
  ('Olpers Cheese Slices 200g', 'Processed cheese slices by Olpers - mild flavour and great melt. A quick and easy topping for burgers, sandwiches and omelettes.', 510, 'https://images.unsplash.com/photo-1618164436241-4473940d1f5c?w=400', 50, 'c0000001-0000-0000-0000-000000000001'),
  ('Kraft Processed Cheese Slices 200g', 'The globally trusted Kraft cheese slices. Rich, creamy and perfectly meltable. Available at major supermarkets in Islamabad for an authentic burger experience.', 780, 'https://images.unsplash.com/photo-1618164436241-4473940d1f5c?w=400', 30, 'c0000001-0000-0000-0000-000000000001'),
  ('Philadelphia Cream Cheese 200g', 'Kraft iconic cream cheese. Smooth, spreadable and lightly tangy. Essential for cheesecakes, cream cheese frosting, bagels and creamy pasta sauces.', 1100, 'https://images.unsplash.com/photo-1618164436241-4473940d1f5c?w=400', 20, 'c0000001-0000-0000-0000-000000000001'),
  ('Nurpur Yogurt 400g', 'Full-fat fresh dahi made from pure cow milk. Thick, creamy and mildly tangy - perfect for raita, lassi, marinades or eating plain with paratha.', 165, 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=400', 80, 'c0000001-0000-0000-0000-000000000001'),
  ('Haleeb Yogurt 400g', 'Smooth, consistent yogurt from Haleeb. Available fresh through cold-chain distribution. Great for cooking, raita and everyday dahi use.', 145, 'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=400', 70, 'c0000001-0000-0000-0000-000000000001'),
  ('Olpers Cream 200ml', 'UHT cream by Olpers - full-fat and shelf-stable. Use it in gravies, desserts, pasta or whip it for cakes. Consistent quality every time.', 240, 'https://images.unsplash.com/photo-1563636619-e9143da7973b?w=400', 60, 'c0000001-0000-0000-0000-000000000001'),
  ('Nurpur Fresh Cream 200ml', 'Full-fat cream with a rich, natural taste. Ideal for making creamy curries, kheer, halwa and dessert toppings.', 250, 'https://images.unsplash.com/photo-1563636619-e9143da7973b?w=400', 55, 'c0000001-0000-0000-0000-000000000001');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Falak Basmati Rice 5kg', 'Premium aged basmati - top-selling rice brand in Pakistan. Long, slender grains that elongate beautifully on cooking. Fragrant, fluffy and never sticky. The gold standard for biryani and pulao.', 1350, 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=400', 100, 'c0000001-0000-0000-0000-000000000002'),
  ('Sunridge Rozana Basmati Rice 5kg', 'Everyday basmati from Sunridge - consistent quality at great value. Aged grain, medium-long and wonderfully fragrant. Ideal for daily chawal, khichdi and biryani.', 1150, 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=400', 90, 'c0000001-0000-0000-0000-000000000002'),
  ('Guard Basmati Rice 5kg', 'Trusted basmati brand widely available across Rawalpindi and Islamabad. Clean grain, good fragrance and consistent cook - a solid everyday rice for the whole family.', 1200, 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=400', 85, 'c0000001-0000-0000-0000-000000000002'),
  ('Kernel Super Basmati Rice 5kg', 'Extra-long Super Kernel Basmati preferred by restaurants and discerning cooks. Each grain cooks separate and firm with a signature aroma that fills the kitchen.', 1450, 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=400', 60, 'c0000001-0000-0000-0000-000000000002'),
  ('Sunridge Chakki Atta 10kg', 'Whole wheat chakki-ground atta fortified with Iron, Zinc and Folic Acid. Makes soft, pliable dough for rotis and parathas. Pakistan most trusted everyday flour brand.', 1450, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 80, 'c0000001-0000-0000-0000-000000000002'),
  ('Sunridge Chakki Atta 5kg', 'Sunridge classic chakki atta in a convenient 5kg pack. Same fortified whole wheat goodness - ideal for smaller households or topping up.', 760, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 100, 'c0000001-0000-0000-0000-000000000002'),
  ('Bake Parlor Chakki Atta 10kg', 'Popular branded atta widely available in Rawalpindi kiryana stores and supermarkets. Good dough consistency with a natural wheat aroma. Solid everyday value.', 1380, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 75, 'c0000001-0000-0000-0000-000000000002'),
  ('Sunridge Maida 1kg', 'Finely refined all-purpose flour (maida) by Sunridge. Essential for naan, puri, biscuits, cakes and pastries. Smooth texture for consistent baking results.', 180, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 120, 'c0000001-0000-0000-0000-000000000002'),
  ('Sunridge Suji Semolina 1kg', 'Coarse-ground semolina for halwa, sewaiyan and rava dishes. Sunridge suji is clean-milled, consistent in texture and gives a perfectly golden result when toasted.', 175, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 110, 'c0000001-0000-0000-0000-000000000002'),
  ('Sunridge Besan Gram Flour 1kg', 'Fine-ground chickpea flour - the base of pakoras, batter frying, kadhi and traditional mithai. Sunridge besan is consistent in grind and free from adulteration.', 210, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 100, 'c0000001-0000-0000-0000-000000000002'),
  ('Rafhan Corn Flour 300g', 'Fine white corn starch for thickening gravies, soups, custards and sauces. Gives a clean, neutral thickening with no starchy aftertaste. Also used for crispy fried coatings.', 165, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 95, 'c0000001-0000-0000-0000-000000000002'),
  ('Rafhan Custard Powder 300g', 'Classic vanilla custard powder by Rafhan. Makes a thick, creamy dessert custard in minutes. Also used as corn starch for baking. A tea-time favourite for generations.', 290, 'https://images.unsplash.com/photo-1574323347407-f5e1ad6d020b?w=400', 80, 'c0000001-0000-0000-0000-000000000002');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Masoor Dal Red Lentil 1kg', 'Split red lentils - the most widely cooked daal in Pakistani homes. Quick to prepare, mild in flavour and rich in protein and iron. Makes a thick, comforting dal with a squeeze of lemon.', 360, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 150, 'c0000001-0000-0000-0000-000000000003'),
  ('Moong Dal Yellow Split 1kg', 'Hulled yellow moong dal - light, easily digestible and nutritious. Perfect for daily dal, khichdi and soups. A favourite for children and those with sensitive stomachs.', 480, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 120, 'c0000001-0000-0000-0000-000000000003'),
  ('Chana Dal Split Chickpea 1kg', 'Coarse-ground split chickpea dal with a slightly nutty, rich flavour. Used in chana dal curry, haleem, daal gosht and as a binding agent in shami kabab.', 350, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 130, 'c0000001-0000-0000-0000-000000000003'),
  ('Mash Dal White Urad 1kg', 'Split white urad dal - the essential base of North Pakistani daal mash. A staple served with naan at dhabas and restaurants across Rawalpindi. Rich, creamy and deeply satisfying.', 620, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 90, 'c0000001-0000-0000-0000-000000000003'),
  ('Kabuli Chana Whole Chickpeas 1kg', 'Large, round white chickpeas - the base for chana chaat, cholay puri and hummus. Soak overnight for best results. High in fibre and plant protein.', 460, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 110, 'c0000001-0000-0000-0000-000000000003'),
  ('Whole Moong Green Gram 1kg', 'Whole green mung beans with the hull on. Sprout them for a fresh salad topping or cook as a wholesome mung bean curry. High in protein and micronutrients.', 420, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 100, 'c0000001-0000-0000-0000-000000000003'),
  ('Kali Dal Whole Black Urad 1kg', 'Whole black gram with skin - the key ingredient in authentic makhani dal. Slow-cooks into a buttery, hearty dish. Rich in fibre and a North Pakistani classic.', 580, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 85, 'c0000001-0000-0000-0000-000000000003'),
  ('Toor Dal Pigeon Pea 1kg', 'Yellow split pigeon peas used in Sindhi and South Asian cooking. Makes a mildly sweet, protein-rich dal. Also used in sambar and mixed dal dishes.', 390, 'https://images.unsplash.com/photo-1515543904379-3d757afe72e4?w=400', 95, 'c0000001-0000-0000-0000-000000000003');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Dalda Cooking Oil 1L', 'Pakistan market-leading cooking oil. Fortified with Vitamins A, D and E. Neutral flavour, high smoke point and consistent quality for deep frying, sauteing and baking.', 530, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 160, 'c0000001-0000-0000-0000-000000000004'),
  ('Dalda Cooking Oil 5L', 'Economy family pack of Pakistan number 1 cooking oil. Same great Vitamin-enriched, neutral-tasting and high-smoke-point quality - in bulk for households that cook daily.', 2450, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 70, 'c0000001-0000-0000-0000-000000000004'),
  ('Habib Cooking Oil 1L', 'Vitamin A, D and E enriched blended vegetable oil from Habib. Clean flavour and reliable for all cooking methods. Well distributed across Rawalpindi and Islamabad markets.', 520, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 120, 'c0000001-0000-0000-0000-000000000004'),
  ('Meezan Cooking Oil 1L', 'A rising brand known for using natural ingredients with minimal processing. Mild taste and good frying performance. Gaining popularity in health-conscious households.', 510, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 110, 'c0000001-0000-0000-0000-000000000004'),
  ('Sufi Cooking Oil 1L', 'Over 30 years in the Pakistani cooking oil market. Reliable quality, widely distributed and a trusted name in Rawalpindi homes and restaurants.', 490, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 100, 'c0000001-0000-0000-0000-000000000004'),
  ('Kashmir Cooking Oil 1L', 'One of the fastest-growing local cooking oil brands. Vitamin-enriched, light colour and clean taste. Rapidly gaining shelf space across Rawalpindi kiryana stores.', 475, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 95, 'c0000001-0000-0000-0000-000000000004'),
  ('Eva Canola Oil 1L', 'Premium heart-healthy canola oil - low in saturated fats, high in monounsaturated fats and cholesterol-free. Light flavour that does not overpower food. Ideal for salad dressings and baking.', 680, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 75, 'c0000001-0000-0000-0000-000000000004'),
  ('Sufi Sunflower Oil 1L', 'Pakistan best-known sunflower oil - rich in Vitamin E, light in taste and ideal for high-heat cooking. A healthier alternative to standard cooking oils for frying and sauteing.', 560, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 90, 'c0000001-0000-0000-0000-000000000004'),
  ('Rahma Olive Oil 500ml', 'Premium cold-pressed olive oil for salad dressings, dips and light sauteing. Rich in antioxidants and heart-healthy monounsaturated fats. Locally branded and widely available in Islamabad.', 1450, 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=400', 45, 'c0000001-0000-0000-0000-000000000004'),
  ('Dalda Banaspati Ghee 1kg', 'Pakistan oldest and most iconic banaspati ghee brand. Rich, buttery flavour that makes parathas, halwa and biryani taste authentic. A kitchen essential in every Pakistani household.', 750, 'https://images.unsplash.com/photo-1567093321-1d0e39c38c6c?w=400', 130, 'c0000001-0000-0000-0000-000000000004'),
  ('Meezan Banaspati Ghee 1kg', 'Popular banaspati ghee with a clean, mild flavour. Great for frying, parathas and desi sweets. Widely stocked in Rawalpindi and Islamabad grocery stores.', 720, 'https://images.unsplash.com/photo-1567093321-1d0e39c38c6c?w=400', 110, 'c0000001-0000-0000-0000-000000000004'),
  ('Nurpur Desi Ghee 1kg', 'Premium pure desi ghee from Nurpur made from cow milk for an authentic, rich flavour. Elevates biryani, daal and traditional halwa to another level. The real deal for desi cooking.', 1850, 'https://images.unsplash.com/photo-1567093321-1d0e39c38c6c?w=400', 40, 'c0000001-0000-0000-0000-000000000004');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Shan Biryani Masala 60g', 'Shan iconic biryani spice mix - a blend of 20 or more whole and ground spices perfected over decades. Makes restaurant-quality biryani at home. Pakistan most beloved recipe masala.', 115, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 200, 'c0000001-0000-0000-0000-000000000005'),
  ('National Biryani Masala 50g', 'National Foods biryani masala - Pakistan market leader in recipe mixes. Bold, balanced spice blend for a fragrant, flavourful biryani. Trusted by Pakistani families for over 50 years.', 105, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 190, 'c0000001-0000-0000-0000-000000000005'),
  ('Shan Nihari Masala 65g', 'Authentic Nihari spice blend from Shan - the slow-cook beef curry from Old Delhi and Lahore. Rich, aromatic and deeply flavoured. Just add beef, ghee and time.', 120, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 160, 'c0000001-0000-0000-0000-000000000005'),
  ('National Qorma Masala 50g', 'Classic qorma spice mix from National Foods. Aromatic blend of coriander, cardamom and warming spices for a rich, creamy qorma. Works beautifully with chicken or mutton.', 100, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 155, 'c0000001-0000-0000-0000-000000000005'),
  ('Shan Chicken Tikka Masala 60g', 'Shan tikka masala blend - smoky, tangy and mildly spiced. Marinade chicken for a minimum of 2 hours and grill or bake for authentic restaurant-style tikka at home.', 115, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 175, 'c0000001-0000-0000-0000-000000000005'),
  ('Shan Haleem Mix 300g', 'Complete spice and grain mix for authentic Haleem - Pakistan most beloved slow-cooked comfort dish. Contains wheat, lentils and a perfectly measured spice blend. Just add meat.', 280, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 90, 'c0000001-0000-0000-0000-000000000005'),
  ('Laziza Biryani Masala 55g', 'Laziza popular biryani mix with a slightly different, fuller flavour profile. A great alternative for cooks who like a touch more richness in their biryani.', 95, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 140, 'c0000001-0000-0000-0000-000000000005'),
  ('Shan Red Chili Powder 200g', 'Pure ground red chili powder from Shan - consistent heat, vibrant colour and clean flavour. Use for curries, marinades and any dish that needs a proper kick.', 190, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 150, 'c0000001-0000-0000-0000-000000000005'),
  ('National Turmeric Powder 200g', 'Bright yellow ground turmeric - the backbone of Pakistani cooking. Anti-inflammatory, flavourful and essential in every curry, marinade and daal. National powder is consistently milled.', 170, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 160, 'c0000001-0000-0000-0000-000000000005'),
  ('Shan Garam Masala 100g', 'Classic whole-spice blend including cloves, cardamom, cinnamon, black pepper and cumin. Freshly ground for a warm, complex aroma. Add a pinch at the end of cooking to elevate any dish.', 175, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 130, 'c0000001-0000-0000-0000-000000000005'),
  ('National Coriander Powder 200g', 'Finely ground coriander - earthy, citrusy and essential in Pakistani curries. National coriander powder is consistently fresh-milled and free from adulteration.', 160, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 145, 'c0000001-0000-0000-0000-000000000005'),
  ('Shan Cumin Seeds Zeera 100g', 'Whole cumin seeds from Shan - aromatic, slightly bitter and essential for tarka, pulao and countless Pakistani dishes. Premium quality, clean and sorted.', 145, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=400', 130, 'c0000001-0000-0000-0000-000000000005');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('National Tomato Ketchup 800g', 'Pakistan number 1 ketchup brand - thick, tangy and perfectly sweet. Made from ripe tomatoes with a signature National flavour. A must-have on every dining table for fries, burgers and samosas.', 340, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 180, 'c0000001-0000-0000-0000-000000000006'),
  ('Mitchells Tomato Ketchup 800g', 'Classic Pakistani ketchup brand since 1933. A rich, full-bodied tomato ketchup made from sun-ripened tomatoes. Bold flavour with a long heritage - a Pakistani kitchen tradition.', 320, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 140, 'c0000001-0000-0000-0000-000000000006'),
  ('Shangrila Ketchup 800g', 'Popular local ketchup with a slightly sweeter, smoother profile. Great value for the taste. A widely stocked alternative to National and Mitchells across Rawalpindi stores.', 300, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 120, 'c0000001-0000-0000-0000-000000000006'),
  ('Knorr Chilli Garlic Sauce 300g', 'Unilever Knorr chilli garlic sauce - mildly hot, deeply garlicky and incredibly versatile. The most commonly used dipping sauce in Rawalpindi restaurants and homes alike.', 280, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 160, 'c0000001-0000-0000-0000-000000000006'),
  ('National Mayonnaise 500g', 'Creamy, tangy mayonnaise from National Foods. Thick consistency, mild flavour and great for burgers, sandwiches, coleslaw and as a dip base. Locally made and budget-friendly.', 350, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 130, 'c0000001-0000-0000-0000-000000000006'),
  ('Knorr Mayonnaise 300g', 'Smooth, rich mayonnaise from Knorr - slightly richer and tangier than local brands. Ideal for club sandwiches, wraps and as a base for dips and dressings.', 310, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 110, 'c0000001-0000-0000-0000-000000000006'),
  ('National Mango Achaar 400g', 'Pakistan favourite mango pickle - raw mango pieces pickled in mustard oil with chili, fennel and spices. The perfect side for daal chawal, paratha and biryani. Tangy, spicy and addictive.', 230, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 150, 'c0000001-0000-0000-0000-000000000006'),
  ('Shan Mixed Achaar 320g', 'Shan popular mixed pickle - a blend of mango, carrot, lime and chili in spiced oil. A burst of tangy heat with every bite. Goes with almost everything.', 210, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 130, 'c0000001-0000-0000-0000-000000000006'),
  ('National Ginger Garlic Paste 750g', 'Ready-to-use ginger and garlic paste - the essential base of almost every Pakistani curry. National paste is consistent, pungent and saves 10 minutes of prep every single day.', 390, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 170, 'c0000001-0000-0000-0000-000000000006'),
  ('Shan Ginger Garlic Paste 700g', 'Freshly ground ginger-garlic paste from Shan - bold flavour with no additives. Stored in airtight packaging to keep fresh. A cooking shortcut no Pakistani kitchen can do without.', 370, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 155, 'c0000001-0000-0000-0000-000000000006'),
  ('Knorr Chicken Cubes 20 Pack', 'Concentrated chicken flavour cubes - Unilever Knorr, the most used cooking cube in Pakistani kitchens. Adds depth to soups, rice and gravies instantly. 20 cubes per pack.', 195, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 180, 'c0000001-0000-0000-0000-000000000006'),
  ('National Soy Sauce 300ml', 'Light soy sauce for Chinese-style cooking, stir-fries and marinades. National soy sauce is the most commonly available in Rawalpindi stores - clean, salty and umami-rich.', 180, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 120, 'c0000001-0000-0000-0000-000000000006'),
  ('Rooh Afza Sharbat 750ml', 'Hamdard iconic rose-flavoured sharbat - a Pakistani institution since 1907. Mix with chilled water or milk for a refreshing drink. A Ramadan and summer absolute essential.', 680, 'https://images.unsplash.com/photo-1613478223719-2ab802602423?w=400', 100, 'c0000001-0000-0000-0000-000000000006'),
  ('National Vinegar 800ml', 'Clean white vinegar for pickling, chutneys, salad dressings and cleaning. National vinegar is consistently acidic and free from impurities - the everyday kitchen staple.', 140, 'https://images.unsplash.com/photo-1589156229687-496a31ad1d1f?w=400', 100, 'c0000001-0000-0000-0000-000000000006'),
  ('National Pizza Sauce 300g', 'Ready-to-use pizza and pasta sauce from National Foods. Tomato-rich, herbed and slightly sweet. Just spread on dough and top with your favourite ingredients for a homemade pizza night.', 210, 'https://images.unsplash.com/photo-1607451486597-52e6b4a36a4e?w=400', 90, 'c0000001-0000-0000-0000-000000000006');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Tapal Danedar 500g', 'Pakistan number 1 tea brand - Tapal Danedar. Strong, bold and full-bodied black tea that brews a deeply coloured, aromatic cup. The backbone of the perfect desi chai. A household name since 1947.', 1050, 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400', 200, 'c0000001-0000-0000-0000-000000000007'),
  ('Brooke Bond Supreme 500g', 'Unilever Red Label - the deeply traditional Pakistani chai tea. Strong, malty and warming. A brand that has been in Pakistani homes for generations. Makes a satisfying doodh patti every time.', 1020, 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400', 170, 'c0000001-0000-0000-0000-000000000007'),
  ('Vital Eastern Tea 500g', 'A strong third contender in the Islamabad market. Vital Eastern tea is known for its robust flavour and good value. Preferred by many Islamabad residents.', 980, 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400', 130, 'c0000001-0000-0000-0000-000000000007'),
  ('Lipton Yellow Label Tea Bags 100 Pack', 'Multinational tea brand with 100 tea bags. Each bag gives a bright, clean, medium-strength cup. Popular in offices and with those who prefer a lighter, less tannic brew.', 680, 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400', 110, 'c0000001-0000-0000-0000-000000000007'),
  ('Tapal Green Tea 30 Bags', 'Tapal green tea in convenient bags. Mild, grassy and naturally low in caffeine. Rich in antioxidants. A popular healthy switch for those reducing their doodh patti intake.', 380, 'https://images.unsplash.com/photo-1556909114-f6e7ad7d3136?w=400', 100, 'c0000001-0000-0000-0000-000000000007'),
  ('Nescafe Classic Instant Coffee 100g', 'The most widely sold instant coffee in Pakistan. Smooth, medium-roasted and easy to dissolve. A quick coffee fix for home and office - ready in 30 seconds with hot water or milk.', 790, 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=400', 120, 'c0000001-0000-0000-0000-000000000007'),
  ('Nescafe 3-in-1 Sachets 20 Pack', 'Coffee, creamer and sugar combined in one sachet. Just add hot water and stir. The most convenient way to enjoy a consistent, sweet cup of coffee at home, at work or on the go.', 580, 'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=400', 140, 'c0000001-0000-0000-0000-000000000007'),
  ('Pepsi 1.5L', 'PepsiCo iconic cola - bold cola flavour, high carbonation and ice cold refreshment. A party and BBQ essential.', 175, 'https://images.unsplash.com/photo-1629203851122-3726ecdf080e?w=400', 200, 'c0000001-0000-0000-0000-000000000007'),
  ('Coca-Cola 1.5L', 'The world most recognised soft drink. Smooth cola with a distinctive caramel sweetness. Best served ice cold.', 175, 'https://images.unsplash.com/photo-1629203851122-3726ecdf080e?w=400', 190, 'c0000001-0000-0000-0000-000000000007'),
  ('7Up 1.5L', 'Crisp lemon-lime carbonated drink from PepsiCo. Naturally caffeine-free and refreshing. Perfect as a standalone drink or mixer.', 165, 'https://images.unsplash.com/photo-1629203851122-3726ecdf080e?w=400', 170, 'c0000001-0000-0000-0000-000000000007'),
  ('Pakola Ice Cream Soda 500ml', 'Pakistan iconic bright-green fizzy drink. Creamy, vanilla-sweet and utterly unique. Pakola is a cultural institution - you cannot visit Rawalpindi without cracking one open.', 90, 'https://images.unsplash.com/photo-1629203851122-3726ecdf080e?w=400', 150, 'c0000001-0000-0000-0000-000000000007'),
  ('Nestle Fruita Vitals Apple 1L', 'Nestle premium fruit drink with real fruit juice. Apple flavour - not-too-sweet, clean and refreshing. Fortified with vitamins for an everyday healthy drink.', 290, 'https://images.unsplash.com/photo-1621506289937-a8e4df240d0b?w=400', 100, 'c0000001-0000-0000-0000-000000000007'),
  ('Shezan Apple Juice 1L', 'Pakistan most widely available fruit juice brand. Shezan apple juice has a classic, consistent flavour loved by kids and adults alike. Made from concentrated apple juice.', 270, 'https://images.unsplash.com/photo-1621506289937-a8e4df240d0b?w=400', 110, 'c0000001-0000-0000-0000-000000000007'),
  ('Shezan Mango Juice 1L', 'Rich, thick mango nectar from Shezan. Made from Pakistani Chaunsa mangoes considered among the finest in the world. The taste of summer in every Tetra Pak.', 280, 'https://images.unsplash.com/photo-1621506289937-a8e4df240d0b?w=400', 105, 'c0000001-0000-0000-0000-000000000007'),
  ('Tang Orange Powder 500g', 'The iconic orange-flavoured instant drink powder. Just add cold water and stir. Market leader in Pakistan powdered drink category. Great for making a quick pitcher for the family.', 380, 'https://images.unsplash.com/photo-1621506289937-a8e4df240d0b?w=400', 150, 'c0000001-0000-0000-0000-000000000007'),
  ('Nestle Milo 400g', 'The beloved chocolate malt drink from Nestle. Rich, chocolatey and fortified with 8 vitamins and minerals. A morning essential for kids and a nostalgic favourite for adults. Mix with hot or cold milk.', 640, 'https://images.unsplash.com/photo-1561758033-d89a9ad46330?w=400', 120, 'c0000001-0000-0000-0000-000000000007'),
  ('Nestle Pure Life Water 1.5L', 'Pakistan number 1 bottled water brand. Purified through multi-step filtration with added minerals for a clean, balanced taste. Essential for homes, offices and on-the-go.', 95, 'https://images.unsplash.com/photo-1560765447-e4c0ca6c5c1c?w=400', 300, 'c0000001-0000-0000-0000-000000000007'),
  ('Red Bull Energy Drink 250ml', 'The world number 1 premium energy drink. Contains caffeine, taurine and B-vitamins for a boost in focus and energy. Available at select Islamabad supermarkets and petrol stations.', 320, 'https://images.unsplash.com/photo-1629203851122-3726ecdf080e?w=400', 50, 'c0000001-0000-0000-0000-000000000007');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Vim Dishwash Bar 250g', 'The most widely used dishwash bar in Pakistan. Powerful grease-cutting formula with a lemon fresh scent. Works on dishes, pots and pans - effective even in cold water.', 110, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 250, 'c0000001-0000-0000-0000-000000000008'),
  ('Lemon Max Dishwash Bar 250g', 'Popular dishwash bar with a zesty lemon fragrance. Strong on grease, gentle on hands. A kiryana-store staple across Rawalpindi and Islamabad.', 100, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 220, 'c0000001-0000-0000-0000-000000000008'),
  ('Vim Liquid Dishwash Lemon 500ml', 'Concentrated lemon Vim liquid - a few drops cut through heavy grease on dishes, glasses and utensils. Leaves everything squeaky clean with a fresh citrus scent.', 260, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 160, 'c0000001-0000-0000-0000-000000000008'),
  ('Harpic Toilet Cleaner 500ml', 'Reckitt market-leading toilet bowl cleaner. Powerful formula that removes limescale, stains and kills 99.9 percent of bacteria. A bathroom essential for weekly deep cleaning.', 320, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 150, 'c0000001-0000-0000-0000-000000000008'),
  ('Dettol Antiseptic Liquid 500ml', 'The trusted multi-purpose antiseptic from Dettol. Use diluted for floor mopping, surface sanitisation and minor wound cleaning. Kills bacteria and viruses on contact.', 390, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 130, 'c0000001-0000-0000-0000-000000000008'),
  ('Mortein Insect Killer Spray 300ml', 'Pakistan most widely used aerosol insecticide. Fast-acting formula kills mosquitoes, flies, cockroaches and ants on contact. Essential for homes during summer months.', 400, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 120, 'c0000001-0000-0000-0000-000000000008'),
  ('Rose Petal Tissues 200 Sheets', 'Pakistan most widely available tissue brand. Soft, 2-ply sheets for everyday use at the table, face and nose. Available in every grocery store and kiryana across Rawalpindi.', 150, 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=400', 200, 'c0000001-0000-0000-0000-000000000008'),
  ('Dettol Antibacterial Wet Wipes 72 Pack', 'Ready-to-use antibacterial wet wipes for surfaces, hands and on-the-go sanitisation. Kills 99.9 percent of bacteria without water or rinsing. Great for kitchen counters and travel.', 390, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 100, 'c0000001-0000-0000-0000-000000000008'),
  ('Fineline Glass Cleaner 500ml', 'Streak-free glass and surface cleaner. Leaves mirrors, windows and glass tables sparkling clean with no residue. Widely stocked across Rawalpindi supermarkets.', 195, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 110, 'c0000001-0000-0000-0000-000000000008'),
  ('Domex Floor Cleaner 500ml', 'Unilever Domex multi-purpose floor cleaner. Kills germs on floors, tiles and bathroom surfaces. Pine-fresh scent that lingers. Effective on tough stains and grime.', 280, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400', 120, 'c0000001-0000-0000-0000-000000000008');
INSERT INTO products (name, description, price, image, stock, category_id) VALUES
  ('Surf Excel Washing Powder 1kg', 'Heritage laundry detergent brand - one of Pakistan most trusted. Superior stain-removal performance with a fresh fragrance. Works on all fabrics in both hand-wash and machine-wash.', 540, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 160, 'c0000001-0000-0000-0000-000000000009'),
  ('Ariel Washing Powder 1kg', 'Ariel - the strongest stain-removing detergent on the market. Enzyme-based formula dissolves even set-in stains like oil, curry and blood. Recommended for white and bright clothing.', 590, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 140, 'c0000001-0000-0000-0000-000000000009'),
  ('Brite Washing Powder 1kg', 'A popular value-for-money washing powder with a strong, long-lasting fragrance. Good foam for handwashing. Available widely in Rawalpindi at an accessible price point.', 430, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 150, 'c0000001-0000-0000-0000-000000000009'),
  ('Surf Excel Laundry Bar 250g', 'Surf Excel classic laundry bar for handwashing collars, cuffs and heavily soiled clothes. Works up a rich lather that cuts through grease and tough stains effectively.', 130, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 180, 'c0000001-0000-0000-0000-000000000009'),
  ('Comfort Fabric Softener 1L', 'Unilever Comfort - Pakistan most widely sold fabric softener. Leaves clothes soft, reduces static and imparts a fresh floral fragrance that lasts after drying. Add to the final rinse.', 430, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 100, 'c0000001-0000-0000-0000-000000000009'),
  ('Vanish Stain Remover Powder 400g', 'Reckitt Vanish - the market leader for stain removal. Oxygen-based formula lifts stains that regular detergent misses. Safe for colours and whites. Pre-treat stubborn stains before washing.', 720, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 75, 'c0000001-0000-0000-0000-000000000009'),
  ('Robin Blue Fabric Whitener 200ml', 'Reckitt iconic Robin Blue - adds a brightening blue optical effect to white cotton and linens. A few drops in the final rinse keeps whites dazzling. A household tradition for decades.', 180, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 130, 'c0000001-0000-0000-0000-000000000009'),
  ('Ariel Liquid Detergent 1L', 'Ariel liquid detergent for automatic front-load and top-load washing machines. Dissolves instantly in cold water, protects fabric colour and removes 20 types of stains in a single wash.', 650, 'https://images.unsplash.com/photo-1582735689369-4fe89db7114c?w=400', 80, 'c0000001-0000-0000-0000-000000000009');
